################################
##########REV NOTES#############
# Description
# onClick action for global delete confirmation popup. Receives delete named query path and query parameters from the view parameters.
#
# Initials ... Date ... Change #
# NG ... 05/01/2025 ... Initial Creation
# NG ... 05/20/2025 ... Added .capitalize() to success message with record_type
# NG ... 06/05/2025 ... Modified code to accept new array parameters
# NG ... 06/27/2025 ... Results of queries are now filtered by data type to determine result checking logic
# NG ... 07/17/2025 ... Code now checks if the name of the deleted record was passed into the view and displays it in the confirmation message if it is present

import sys
PyUnicode = sys.modules['org.python.core'].PyUnicode

try:
	query_paths = self.view.params.DeleteNamedQueriesPaths
	query_params = self.view.params.DeleteNamedQueriesParams
	record_type = self.view.params.ObjectBeingDeletedType
	record_name = self.view.params.ObjectBeingDeletedName
	message_handlers = self.view.params.MessageHandlers
	payloads = self.view.params.Payloads

	#if query_path in (None, ""):
	if len(query_paths) == 0:
		raise Exception("Named query path not supplied to delete confirmation popup.")
	if len(query_params) == 0:
		raise Exception("Named query parameters not supplied to delete confirmation popup.")
	query_params_map_array = []
	for params_map in query_params:
		query_params_map = {}
		for key, value in params_map.items():
			query_params_map[key] = value
		query_params_map_array.append(query_params_map.copy())
	for query_path, query_params_map in zip(query_paths, query_params_map_array):
		res = system.db.runNamedQuery(query_path, query_params_map)
		if isinstance(res, PyUnicode):
			if str(res) != "Success": 
				raise Exception(str(res))
			else:
				system.perspective.closePopup('')
		else:
			if str(res[0][0]) != "Success": 
				raise Exception(str(res[0][0]))
			else:
				system.perspective.closePopup('')
	if record_name not in (None, ""):
		gpa.frontEnd.localUI.throwSuccess(str(record_name).capitalize() + " deleted")
	elif record_type not in (None, ""):
		gpa.frontEnd.localUI.throwSuccess(str(record_type).capitalize() + " deleted")
	else:
		gpa.frontEnd.localUI.throwSuccess("Record deleted")

	payloads_map_array = []
	for payload_map in payloads:
		query_payload_map = {}
		for key, value in payload_map.items():
			query_payload_map[key] = value
		payloads_map_array.append(query_payload_map.copy())

	for message_handler, payload in zip(message_handlers, payloads_map_array):
		system.perspective.sendMessage(message_handler, payload)

except Exception as e:
	gpa.frontEnd.localUI.throwError(str(e))
